export function paginate(items, size) {
  if (!Array.isArray(items)) throw new TypeError('items must be an array');
  if (!Number.isInteger(size) || size <= 0) throw new RangeError('size must be a positive integer');
  const pages = [];
  const count = Math.floor(items.length / size);
  for (let page = 0; page < count; page += 1) {
    pages.push(items.slice(page * size, (page + 1) * size));
  }
  // Handle remainder items
  const remainder = items.length % size;
  if (remainder !== 0) {
    const start = count * size;
    pages.push(items.slice(start));
  }
  return pages;
}

