import assert from 'node:assert/strict';
import * as api from './src/paginate.js';
const {paginate}=api;
assert.deepEqual(Object.keys(api), ['paginate']);
let valid_cases=0;
for(let length=0;length<=32;length++) {
  for(let size=1;size<=12;size++) {
    const input=Array.from({length},(_,i)=>i);
    const before=[...input];
    const pages=paginate(input,size);
    assert.deepEqual(pages.flat(),input);
    assert.equal(pages.length,Math.ceil(length/size));
    assert.ok(pages.every((page,i)=>Array.isArray(page)&&page.length>0&&page.length<=size&&(i===pages.length-1||page.length===size)));
    assert.deepEqual(input,before);
    valid_cases++;
  }
}
const invalidSizes=[0,-1,1.5,NaN,Infinity,-Infinity,'2',null,undefined,{},[]];
for(const size of invalidSizes) assert.throws(()=>paginate([1,2],size),RangeError);
const invalidInputs=[null,undefined,'abc',{},5,true];
for(const input of invalidInputs) assert.throws(()=>paginate(input,2),TypeError);
assert.deepEqual(paginate([42],4),[[42]]);
assert.deepEqual(paginate([1,2,3],1),[[1],[2],[3]]);
console.log(JSON.stringify({valid_cases,invalid_size_cases:invalidSizes.length,invalid_input_cases:invalidInputs.length,explicit_requested_boundaries:2,result:'pass'}));
